workflow.configText:
params {
   outdir = 'results'
   fail_mode = 'flaky'
   fail_process = 'ALIGN'
   fail_sample = 'S07'
   time_limit_s = 120
   chunks = 2
}

manifest {
   name = 'spectio/synthetic-scenarios'
   description = 'Synthetic three-stage pipeline with gate points and failure injection for Spectio tests'
   version = '0.1.0'
   nextflowVersion = '!>=25.04.0'
   mainScript = 'main.nf'
}

process {
   cpus = 1
   memory = { 512.MB * task.attempt }
   time = { "${(params.time_limit_s as int) * task.attempt}s" }
   errorStrategy = { (task.exitStatus in [137, 140, 143, Integer.MAX_VALUE] || params.fail_mode == 'flaky') && task.attempt < 3 ? 'retry' : 'terminate' }
   maxRetries = 2
}

trace {
   enabled = true
   overwrite = true
   file = 'results/pipeline_info/execution_trace.txt'
   fields = 'task_id,hash,native_id,process,tag,name,status,exit,attempt,submit,start,complete,realtime,%cpu,peak_rss,workdir'
}

report {
   enabled = true
   overwrite = true
   file = 'results/pipeline_info/execution_report.html'
}

timeline {
   enabled = true
   overwrite = true
   file = 'results/pipeline_info/execution_timeline.html'
}

dag {
   enabled = true
   overwrite = true
   file = 'results/pipeline_info/pipeline_dag.html'
}

executor {
   name = 'local'
   cpus = 2
}

runName = 'intergalactic_montalcini'
outputFormat = 'text'
plugins = ['nf-spectio@0.0.1']
workDir = 'work'

tower {
   enabled = true
   endpoint = 'http://localhost:8765'
}

